// waves.js
//
// The ocean surface is a sum of a few travelling sine swells.
// The exact same maths is used twice:
//   • in JS  -> to place / tilt the surfer so it always sits on the drawn surface
//   • in GLSL (generated below from the same constants) -> to draw the ocean
// Keeping one source of truth is what makes the bird really ride the water.

// dir = travelling direction (unit-ish, in the XZ plane),
// k   = angular wavenumber (2*PI / wavelength),
// amp = height, phase = offset, speed = angular frequency.
export const WAVES = [
  { dir: [0.28, -0.96], k: 0.44, amp: 0.60, phase: 0.0, speed: 0.8 },
  { dir: [-0.86, -0.51], k: 1.0, amp: 0.26, phase: 1.7, speed: 1.3 },
  { dir: [0.93, 0.36], k: 1.9, amp: 0.11, phase: 3.1, speed: 2.0 },
];

export const WAVE_AMP_SUM = WAVES.reduce((s, w) => s + w.amp, 0);

/** Surface height at world position (x, z) and time t. */
export function waveHeight(x, z, t) {
  let h = 0;
  for (let i = 0; i < WAVES.length; i++) {
    const w = WAVES[i];
    h += w.amp * Math.sin(w.k * (w.dir[0] * x + w.dir[1] * z) + w.phase + w.speed * t);
  }
  return h;
}

const _slope = { x: 0, z: 0 };

/** Partial derivatives (dh/dx, dh/dz) of the surface. */
export function waveSlope(x, z, t, out = _slope) {
  out.x = 0;
  out.z = 0;
  for (let i = 0; i < WAVES.length; i++) {
    const w = WAVES[i];
    const c = w.amp * w.k * Math.cos(w.k * (w.dir[0] * x + w.dir[1] * z) + w.phase + w.speed * t);
    out.x += c * w.dir[0];
    out.z += c * w.dir[1];
  }
  return out;
}

/** Up vector of the water surface (length 1). */
export function waveNormalAt(x, z, t, out) {
  const s = waveSlope(x, z, t, _slope);
  return out.set(-s.x, 1, -s.z).normalize();
}

const n = (v) => (Number.isInteger(v) ? v.toFixed(1) : v.toFixed(5));

/** GLSL twin of the three functions above, generated from the same constants. */
export function waveGLSL() {
  const height = [];
  const grad = [];
  for (const w of WAVES) {
    const dir = `vec2(${n(w.dir[0])}, ${n(w.dir[1])})`;
    const ph = `${n(w.k)} * dot(${dir}, p) + ${n(w.phase)} + ${n(w.speed)} * t`;
    height.push(`  h += ${n(w.amp)} * sin(${ph});`);
    grad.push(`  g += ${n(w.amp)} * ${n(w.k)} * ${dir} * cos(${ph});`);
  }
  return `
float surfHeight(vec2 p, float t) {
  float h = 0.0;
${height.join('\n')}
  return h;
}

vec2 surfGrad(vec2 p, float t) {
  vec2 g = vec2(0.0);
${grad.join('\n')}
  return g;
}

vec3 surfNormal(vec2 p, float t) {
  vec2 g = surfGrad(p, t);
  return normalize(vec3(-g.x, 1.0, -g.y));
}
`;
}

// glsl.js — small library of GLSL snippets shared by the sky and the ocean so
// that the horizon colours always agree (the ocean fades into exactly the same
// sky gradient that is drawn behind it).

export const SKY_UNIFORMS = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uZenithColor;
uniform vec3 uHorizonColor;
uniform vec3 uHorizonGlow;
`;

export const SKY_COLOR = /* glsl */ `
vec3 skyColor(vec3 d) {
  float y = clamp(d.y, -0.35, 1.0);
  vec3 col = mix(uHorizonColor, uZenithColor, pow(clamp(y, 0.0, 1.0), 0.52));
  float low = exp(-max(y, 0.0) * 6.5);
  col = mix(col, uHorizonGlow, low * 0.85);
  float s = clamp(dot(d, uSunDir), -1.0, 1.0);
  col += uSunColor * pow(max(s, 0.0), 420.0) * 2.4;   // disc
  col += uSunColor * pow(max(s, 0.0), 16.0) * 0.30;   // halo
  col += uSunColor * pow(max(s, 0.0), 3.0) * 0.16 * low;
  col = mix(col, uHorizonColor * 0.55, smoothstep(0.0, -0.28, y));
  return col;
}
`;

export const NOISE = /* glsl */ `
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    s += a * vnoise(p);
    p = p * 2.03 + vec2(11.3, 7.7);
    a *= 0.5;
  }
  return s;
}
`;

// High frequency ripples. Only ever added to the normal (never to the
// displacement) so they can never alias the geometry.
export const DETAIL_NORMAL = /* glsl */ `
vec3 detailNormal(vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d1 = vec2(0.86, 0.51);
  g += 0.013 * 9.0 * d1 * cos(9.0 * dot(d1, p) + t * 3.1);
  vec2 d2 = vec2(-0.48, 0.88);
  g += 0.0055 * 17.0 * d2 * cos(17.0 * dot(d2, p) + t * 4.3 + 1.3);
  vec2 d3 = vec2(0.31, -0.95);
  g += 0.003 * 33.0 * d3 * cos(33.0 * dot(d3, p) + t * 5.6 + 2.1);
  return vec3(-g.x, 0.0, -g.y);
}
`;

export const CLOUDS = /* glsl */ `
vec3 cloudColor(vec3 d) {
  if (d.y < 0.025) return vec3(0.0);
  vec2 uv = d.xz / max(d.y, 0.03);
  uv = uv * vec2(0.55, 0.85) + vec2(uTime * 0.004, uTime * 0.0022);
  float f = fbm(uv * 1.15 + vec2(3.1, 1.7));
  float f2 = fbm(uv * 0.62 + vec2(-1.2, 4.4));
  float dens = smoothstep(0.46, 0.80, f * 0.78 + f2 * 0.32);
  float vert = smoothstep(0.025, 0.17, d.y) * (1.0 - smoothstep(0.62, 1.0, d.y) * 0.55);
  dens *= vert;
  if (dens < 0.002) return vec3(0.0);
  float lit = clamp((f - fbm(uv * 1.15 + vec2(3.36, 1.7))) * 7.0, -1.0, 1.0);
  float sunAmt = pow(max(dot(d, uSunDir), 0.0), 8.0);
  vec3 darkC = vec3(0.44, 0.46, 0.55);
  vec3 litC = mix(vec3(1.0, 0.94, 0.86), vec3(1.0, 0.78, 0.60), sunAmt * 0.85);
  vec3 c = mix(darkC, litC, lit * 0.5 + 0.5);
  c = mix(c, litC, 0.35);
  return c * dens;
}
`;

// uniforms.js — the shared uniform set + palette.
// The very same uniform objects are referenced by the sky, the ocean and the
// spray shaders, so "uTime" and the sun only need to be updated once.

import * as THREE from 'three';

export const PALETTE = {
  zenith: 0x1b3a63,      // top of the sky
  horizon: 0xd8bf9c,     // warm haze at the horizon
  horizonGlow: 0xf6cb90, // glow just above the water
  sun: 0xfff1d2,
  deep: 0x0a3040,        // troughs
  shallow: 0x2f93a8,     // faces
  foam: 0xf3f9fb,
  island: 0x6e8b9e,
  lighthouse: 0xe8e2d4,
  lighthouseLight: 0xffd27a,
  bird: 0x39404c,
};

// Direction *to* the sun. Low, up-left, beyond the surfer: gives a long
// glitter path on the water and a rim light on the pelican.
export const SUN_DIR = new THREE.Vector3(-0.076, 0.246, 0.965).normalize();

export function createSharedUniforms() {
  return {
    uTime: { value: 0 },
    uSunDir: { value: SUN_DIR.clone() },
    uSunColor: { value: new THREE.Color(PALETTE.sun) },
    uZenithColor: { value: new THREE.Color(PALETTE.zenith) },
    uHorizonColor: { value: new THREE.Color(PALETTE.horizon) },
    uHorizonGlow: { value: new THREE.Color(PALETTE.horizonGlow) },
  };
}

// sky.js — a huge inverted sphere that is pinned to the camera and painted with
// the same gradient the ocean fades into. Sun disc, halo, drifting cloud banks.

import * as THREE from 'three';
import { SKY_UNIFORMS, SKY_COLOR, NOISE, CLOUDS } from './glsl.js';

const VERT = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;            // the dome is centred on the camera
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const FRAG = /* glsl */ `
${SKY_UNIFORMS}
${SKY_COLOR}
${NOISE}
${CLOUDS}

varying vec3 vDir;
void main() {
  vec3 d = normalize(vDir);
  vec3 col = skyColor(d);
  col += cloudColor(d);
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createSky(shared) {
  const geometry = new THREE.SphereGeometry(3000, 48, 28);
  const material = new THREE.ShaderMaterial({
    vertexShader: VERT,
    fragmentShader: FRAG,
    uniforms: shared,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false,
    fog: false,
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.renderOrder = -1000;
  mesh.frustumCulled = false;
  mesh.name = 'sky';

  mesh.onBeforeRender = () => {
    // keep the dome centred on the camera so it always reads as the sky
    mesh.position.set(0, 0, 0);
  };

  return {
    mesh,
    update(camera) {
      mesh.position.copy(camera.position);
    },
  };
}

// ocean.js — the sea. A large grid displaced in the vertex shader by the
// shared swell function, then lit by hand in the fragment shader: fresnel sky
// reflection, sun glitter, caps of white water, and a permanent foam wake
// trailing behind the surfer.

import * as THREE from 'three';
import { waveGLSL } from './waves.js';
import { SKY_UNIFORMS, SKY_COLOR, NOISE, DETAIL_NORMAL } from './glsl.js';
import { PALETTE } from './uniforms.js';

export const OCEAN_SIZE = 760;
const SEGMENTS = 384;

const VERT = /* glsl */ `
uniform float uTime;
${waveGLSL()}

varying vec3 vWorld;
varying vec3 vNrm;
varying float vH;

void main() {
  vec3 p = position;
  float h = surfHeight(p.xz, uTime);
  p.y += h;
  vec3 n = surfNormal(p.xz, uTime);
  vec4 wp = modelMatrix * vec4(p, 1.0);
  vWorld = wp.xyz;
  vNrm = normalize(mat3(modelMatrix) * n);
  vH = h;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const FRAG = /* glsl */ `
precision highp float;

${SKY_UNIFORMS}
${waveGLSL()}
${NOISE}
${DETAIL_NORMAL}

uniform float uTime;
uniform vec3 uDeepColor;
uniform vec3 uShallowColor;
uniform vec3 uFoamColor;
uniform vec2 uSurfer;
uniform vec2 uTravelDir;
uniform float uSurferRadius;
uniform float uFogDensity;

varying vec3 vWorld;
varying vec3 vNrm;
varying float vH;

// lower resolution noise far away, where it would otherwise alias
vec2 foamUV(vec2 p, float dist) {
  float lod = clamp(dist / 210.0, 0.14, 1.0);
  return p * lod;
}

void main() {
  vec3 V = normalize(cameraPosition - vWorld);
  float dist = length(cameraPosition - vWorld);

  vec3 N = normalize(vNrm);
  float detail = 1.0 - smoothstep(18.0, 240.0, dist);
  N = normalize(N + detailNormal(vWorld.xz, uTime) * detail * 0.55);

  // water body: darker in the troughs, glowing turquoise where it is thin
  float hn = clamp(vH * 0.62 + 0.5, 0.0, 1.0);
  vec3 water = mix(uDeepColor, uShallowColor, pow(hn, 1.35));
  water += uShallowColor * pow(1.0 - clamp(N.y, 0.0, 1.0), 2.0) * 0.5 * hn;

  // sky reflection (view direction towards the horizon)
  vec3 hdir = normalize(vec3(vWorld.x - cameraPosition.x, 0.06, vWorld.z - cameraPosition.z));
  vec3 R = reflect(-V, N);
  float sunR = max(dot(R, uSunDir), 0.0);

  vec3 refl = skyColor(hdir);
  refl += uSunColor * pow(sunR, 90.0) * 0.5;
  float fres = 0.02 + 0.98 * pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 5.0);
  vec3 col = mix(water, refl, clamp(fres, 0.0, 1.0));

  // sun glitter
  col += uSunColor * (pow(sunR, 260.0) * 1.6 + pow(sunR, 26.0) * 0.30) * (0.35 + 0.9 * detail);

  // ---- white water ---------------------------------------------------------
  vec2 g = surfGrad(vWorld.xz, uTime);
  float steep = length(g);
  float caps = smoothstep(0.62, 1.25, steep) * smoothstep(0.18, 0.60, vH);

  vec2 rel = vWorld.xz - uSurfer;
  float rr = uSurferRadius * (1.0 + 0.10 * sin(uTime * 3.1));
  float rag = fbm(foamUV(vWorld.xz, dist) * 1.9 + vec2(uTime * 1.4, -uTime * 0.9));
  float collar = smoothstep(rr * (1.15 + 0.30 * rag), rr * 0.30, length(rel));

  float along = dot(rel, uTravelDir);
  float side = dot(rel, vec2(-uTravelDir.y, uTravelDir.x));
  float wakeMask = smoothstep(1.5, 16.0, -along) * smoothstep(150.0, 45.0, -along);
  float wakeN = fbm(foamUV(vec2(along, side), dist) * 1.3 + vec2(-uTime * 2.2, 0.0));
  float wake = exp(-abs(side) * 0.11) * wakeMask * (0.45 + 0.55 * wakeN);

  float foam = clamp(caps * 0.95 + collar * 0.85 + wake * 0.55 * detail, 0.0, 1.0);
  float sparkle = step(0.86, hash21(floor(vWorld.xz * 6.0 / max(0.25, detail))));
  col = mix(col, uFoamColor * (0.92 + 0.30 * sparkle), foam * 0.92);

  // ---- fade into the very same sky the dome draws --------------------------
  float fog = 1.0 - exp(-pow(dist * uFogDensity, 2.1));
  col = mix(col, skyColor(hdir), clamp(fog, 0.0, 1.0));

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createOcean(shared) {
  const geometry = new THREE.PlaneGeometry(OCEAN_SIZE, OCEAN_SIZE, SEGMENTS, SEGMENTS);
  geometry.rotateX(-Math.PI / 2); // lay it flat: local .xz == world .xz, .y is height

  const uniforms = {
    ...shared,
    uDeepColor: { value: new THREE.Color(PALETTE.deep) },
    uShallowColor: { value: new THREE.Color(PALETTE.shallow) },
    uFoamColor: { value: new THREE.Color(PALETTE.foam) },
    uSurfer: { value: new THREE.Vector2(0, 0) },
    uTravelDir: { value: new THREE.Vector2(1, 0) },
    uSurferRadius: { value: 1.55 },
    uFogDensity: { value: 0.0029 },
  };

  const material = new THREE.ShaderMaterial({
    vertexShader: VERT,
    fragmentShader: FRAG,
    uniforms,
    side: THREE.FrontSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'ocean';
  mesh.frustumCulled = false;

  return {
    mesh,
    uniforms,
    /** near the surface there is a per-swell tendency to show caps first */
    setSurfer(x, z) {
      uniforms.uSurfer.value.set(x, z);
    },
  };
}

