export function createFish(riderRoot) {
  const group = new THREE.Group();      // carries the flight heading
  group.visible = false;
  riderRoot.add(group);

  const model = new THREE.Group();      // the body points along +X
  model.rotation.y = -Math.PI / 2;      // ...so +X ends up facing along +Z
