}
#film .row { position: absolute; display: flex; align-items: center; gap: .8em;
  font-size: clamp(9px, 1.05vw, 13px); letter-spacing: .34em; text-transform: uppercase; }
#film .tl { top: 0; left: 0; }
#film .tr { top: 0; right: 0; letter-spacing: .18em; }
#film .bl { bottom: 0; left: 0; opacity: .75; letter-spacing: .2em; }

#film .rec { width: .62em; height: .62em; border-radius: 50%; background: #e2543c; }
#film .tc { opacity: .85; }

#film .caption {
  position: absolute; left: 0; right: 0; bottom: 3.4vh; text-align: center;
  font-family: Georgia, "Times New Roman", serif; font-style: italic;
  font-size: clamp(15px, 2.5vw, 34px); letter-spacing: .06em; color: #fff6e6;
  text-shadow: 0 2px 22px rgba(0, 0, 0, 0.55);
  opacity: 0; transition: opacity 1.1s ease; padding: 0 8vw;
}
#film .caption.on { opacity: 1; }

#film .vignette {
  position: absolute; inset: 0;
  background: radial-gradient(120% 90% at 50% 46%, rgba(0,0,0,0) 42%, rgba(4,8,12,.42) 100%);
}
#film .grain {
  position: absolute; inset: -100px; opacity: .045; mix-blend-mode: overlay;
  background-repeat: repeat; background-position: 0 0;
  animation: grain 0.9s steps(6) infinite;
}
@keyframes grain {
  0%   { transform: translate3d(0, 0, 0); }
  25%  { transform: translate3d(-22px, 14px, 0); }
  50%  { transform: translate3d(16px, -18px, 0); }
  75%  { transform: translate3d(-12px, -8px, 0); }
  100% { transform: translate3d(8px, 20px, 0); }
}
#fallback { position: fixed; inset: 0; display: grid; place-items: center; padding: 8vw;
  font: 14px/1.6 ui-monospace, monospace; color: #e8dcc8; text-align: center; }
`;

const CAPTIONS = [
  { at: 2.5, dur: 7.5, text: 'dawn patrol' },
  { at: 25.0, dur: 8.0, text: 'he has never been a good flyer' },
  { at: 47.0, dur: 8.0, text: 'but he is an excellent passenger' },
];

export function createHud(stage, cycleSeconds) {
  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const film = document.createElement('div');
  film.id = 'film';
  film.innerHTML = [
    '<div class="bar top"></div>',
    '<div class="bar bot"></div>',
    '<div class="hud">',
    '  <div class="row tl"><span class="rec" id="rec"></span><span>surfing pelican</span></div>',
    '  <div class="row tr"><span class="tc" id="tc">00:00:00</span></div>',
    '  <div class="row bl"><span>16 mm &middot; no birds were hurried</span></div>',
    '</div>',
    '<div class="caption" id="cap"></div>',
    '<div class="vignette"></div>',
    '<div class="grain" id="grain"></div>',
  ].join('');
  stage.appendChild(film);

  // film grain texture, generated on a canvas at runtime
  const g = document.createElement('canvas');
  g.width = 96;
  g.height = 96;
  const gc = g.getContext('2d');
  const img = gc.createImageData(96, 96);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 120 + Math.random() * 135;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
    img.data[i + 3] = 255;
  }
  gc.putImageData(img, 0, 0);
  const grainEl = film.querySelector('#grain');
  grainEl.style.backgroundImage = `url(${g.toDataURL()})`;
  grainEl.style.backgroundSize = '96px 96px';

  const tc = film.querySelector('#tc');
  const cap = film.querySelector('#cap');
  const rec = film.querySelector('#rec');
  let shown = null;

  const pad = (x, n) => String(Math.floor(x)).padStart(n, '0');

  return {
    update(t) {
      const frames = Math.floor((t % 1) * 24);
      tc.textContent = `00:${pad((t / 60) % 60, 2)}:${pad(t % 60, 2)}:${pad(frames, 2)}`;
      rec.style.opacity = (0.35 + 0.65 * (Math.sin(t * 4.2) > 0 ? 1 : 0.12)).toFixed(3);

      // captions loop on the same period as the camera plan
      const phase = ((t % cycleSeconds) + cycleSeconds) % cycleSeconds;
      let active = null;
      for (const c of CAPTIONS) {
        if (phase >= c.at && phase < c.at + c.dur) active = c;
      }
      if (active !== shown) {
        shown = active;
        cap.textContent = active ? active.text : '';
        cap.classList.toggle('on', !!active);
      }
    },
  };
}

export function showFallback(message) {
  const div = document.createElement('div');
  div.id = 'fallback';
  div.textContent = message;
  document.body.appendChild(div);
}

// main.js — Surfing Pelican.
// An animated, non-interactive short film: one pelican, one longboard, one
// swell. Everything below is generated in code; nothing is fetched at runtime.

import * as THREE from 'three';
import { createSharedUniforms, PALETTE, SUN_DIR } from './src/uniforms.js';
import { createSky } from './src/sky.js';
import { createOcean } from './src/ocean.js';
import { createRider } from './src/pelican.js';
import { createSpray, createRipples } from './src/spray.js';
import { createFish } from './src/fish.js';
import { createIsland, createBirds } from './src/extras.js';
import { createCameraRig } from './src/cameraRig.js';
import { createHud, showFallback } from './src/hud.js';
import { waveHeight } from './src/waves.js';

const stage = document.getElementById('stage');

let renderer;
try {
  renderer = new THREE.WebGLRenderer({
    antialias: true,
    powerPreference: 'high-performance',
  });
} catch (err) {
  showFallback('This film needs WebGL, which this browser will not give us.');
  throw err;
}

const MAX_DPR = 2;
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, MAX_DPR));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
stage.appendChild(renderer.domElement);

// ---------------------------------------------------------------------------
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(new THREE.Color(PALETTE.horizon), 90, 640);

const camera = new THREE.PerspectiveCamera(
  41,
  window.innerWidth / Math.max(1, window.innerHeight),
  0.1,
  6000,
);
camera.position.set(-25, 8.5, -29);

// light: low sun behind the bird, cool fill from the camera side
const sunLight = new THREE.DirectionalLight(0xffd9a8, 2.5);
sunLight.position.copy(SUN_DIR).multiplyScalar(120);
scene.add(sunLight);

const fillLight = new THREE.DirectionalLight(0xa9cbe4, 0.9);
fillLight.position.set(28, 16, -46);
scene.add(fillLight);

scene.add(new THREE.HemisphereLight(0x9dc6e8, 0x0b3a46, 0.85));

// ---------------------------------------------------------------------------
const shared = createSharedUniforms();
const sky = createSky(shared);
scene.add(sky.mesh);

const ocean = createOcean(shared);
scene.add(ocean.mesh);

const rider = createRider();
scene.add(rider.root);

const spray = createSpray(rider.root, renderer.domElement.height);
const ripples = createRipples(scene);

const fish = createFish(rider.root);
const island = createIsland();
scene.add(island);
const birds = createBirds();
scene.add(birds.group);

const rig = createCameraRig(camera);
const hud = createHud(stage, rig.total);

// ---------------------------------------------------------------------------
const riderView = {
  position3: new THREE.Vector3(),
  bob: 0,
  bank: 0,
};

const mouthWorld = new THREE.Vector3();
const localTmp = new THREE.Vector3();
const wakeDir = new THREE.Vector3(0.42, 0.9, 0);

let sprayTimer = 0;
let lastNow = performance.now() / 1000;
let filmTime = 0;
let frames = 0;
let frameSum = 0;
let qualityLevel = 0; // 0 = full, 1 = reduced
const DPR_STEPS = [Math.min(window.devicePixelRatio || 1, MAX_DPR), 1, 0.75];

function onResize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / Math.max(1, h);
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(DPR_STEPS[qualityLevel]);
  renderer.setSize(w, h);
  spray.setCanvasHeight(renderer.domElement.height);
}
window.addEventListener('resize', onResize);

function sprayForMotion(steepness) {
  // the board kicks up more water the steeper the wave it is climbing
  const n = 1 + Math.round(steepness * 3);
  spray.emit(
    n,
    -1.15,
    0.16,
    0,
    wakeDir,
    0.42,
    { up: 1.0, speed: 2.4 + steepness * 2.4, size: 0.035 + steepness * 0.02, life: 1.1 },
  );
}

const fishCtx = {
  mouthWorld,
  setBeakOpen: (v) => rider.setBeakOpen(v),
  onLaunch: () => {
    // a fish breaking the surface throws a little fountain of its own
    rider.root.updateMatrixWorld(true);
    const local = rider.root.worldToLocal(localTmp.copy(fish.group.position));
    local.y = 0.05;
    spray.emit(
      26,
      local.x,
      local.y,
      local.z,
      new THREE.Vector3(0.15, 1, -0.2),
      0.85,
      { up: 1.0, speed: 4.2, size: 0.05, life: 1.2 },
    );
    const w = fish.group.getWorldPosition(new THREE.Vector3());
    ripples.spawn(w.x, 0, w.z, 2.2, 1.2);
  },
  onCatch: (world) => {
    rider.swallow();
    rider.root.updateMatrixWorld(true);
    const local = rider.root.worldToLocal(localTmp.copy(world));
    spray.emit(
      16,
      local.x,
      local.y - 0.05,
      local.z,
      new THREE.Vector3(0.2, 0.8, -0.3),
      1.0,
      { up: 1.0, speed: 2.2, size: 0.04, life: 0.9 },
    );
    ripples.spawn(world.x, 0, world.z, 2.8, 1.5);
  },
};

// ---------------------------------------------------------------------------
function frame(now) {
  requestAnimationFrame(frame);

  const t = now / 1000;
  let dt = t - lastNow;
  lastNow = t;
  if (dt <= 0) return;
  dt = Math.min(dt, 0.1);
  filmTime += dt;

  shared.uTime.value = filmTime;

  rider.root.updateMatrixWorld(true);
  const state = rider.update(dt, filmTime);
  rider.mouthWorld(mouthWorld);

  // the ocean needs to know where the surfer is (foam collar + wake)
  ocean.setSurfer(state.x, state.z);

  // continuous spray off the tail of the board
  sprayTimer -= dt;
  if (sprayTimer <= 0) {
    sprayTimer = 0.055;
    sprayForMotion(Math.min(1, Math.abs(state.normal.x) * 1.6 + (state.fwd.y > 0 ? 0.25 : 0)));
  }

  fish.update(dt, filmTime, fishCtx);
  island.update(filmTime);
  birds.update(filmTime);
  ripples.update(dt, filmTime, waveHeight);

  riderView.position3.copy(rider.root.position);
  riderView.bob = rider.rig.position.y - 0.105;
  riderView.bank = -rider.rig.rotation.x;
  rig.update(filmTime, dt, riderView);
  sky.update(camera);

  hud.update(filmTime);

  renderer.render(scene, camera);

  // ---- gentle adaptive resolution (keeps the iframe happy on slow GPUs) ----
  frameSum += dt;
  frames++;
  if (frames >= 80) {
    const avg = frameSum / frames;
    frames = 0;
    frameSum = 0;
