// TEMPORARY smoke-test harness (not part of the film, deleted before delivery).
// Lets exactly a few *real* rAF frames through (so the compositor can capture
// the canvas) and reports shader/timing diagnostics.
const FRAMES = 6;
let budget = FRAMES;
const realRaf = window.requestAnimationFrame.bind(window);
window.requestAnimationFrame = (cb) => {
  if (budget-- <= 0) return 0;
  return realRaf((ts) => cb(ts));
};

await import('./main.js');

setTimeout(() => {
  const r = window.__pelican?.renderer;
  let info = 'no renderer';
  if (r) {
    const gl = r.getContext();
    const c = r.domElement;
    const px = new Uint8Array(4);
    gl.readPixels(
      Math.floor(c.width / 2),
      Math.floor(c.height / 2),
      1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px,
    );
    info =
      'canvas=' + c.width + 'x' + c.height +
      ' center=' + px.slice(0, 3).join(',') +
      ' programs=' + r.info.programs.length +
      ' frame=' + r.info.render.frame +
      ' calls=' + r.info.render.calls +
      ' tris=' + r.info.render.triangles +
      ' glErr=' + gl.getError();
  }
  console.log('SMOKE ' + info);
  console.log('SMOKE DONE');
}, 4000);

// TEMPORARY smoke-test harness (not part of the film, deleted before delivery).
// Runs the real rAF loop but feeds it a nearly-frozen clock, so a chosen moment
// of the film stays on screen long enough to be screenshotted.
const target = Math.max(0, Number(new URLSearchParams(location.search).get('t')) || 0) + 3;
const MAX_FRAMES = 4000;
let n = 0;
const realRaf = window.requestAnimationFrame.bind(window);
window.requestAnimationFrame = (cb) => {
  if (n++ >= MAX_FRAMES) return 0;
  return realRaf(() => cb(target * 1000 + n * 1.0));
};

await import('./main.js');

setTimeout(() => {
  const r = window.__pelican?.renderer;
  if (r) {
    const gl = r.getContext();
    const c = r.domElement;
    const px = new Uint8Array(4);
    gl.readPixels(
      Math.floor(c.width / 2), Math.floor(c.height / 2),
      1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px,
    );
    console.log(
      'SMOKE canvas=' + c.width + 'x' + c.height +
      ' center=' + px.slice(0, 3).join(',') +
      ' programs=' + r.info.programs.length +
      ' frame=' + r.info.render.frame +
      ' calls=' + r.info.render.calls + ' tris=' + r.info.render.triangles +
      ' glErr=' + gl.getError(),
    );
  }
  console.log('SMOKE DONE');
}, 6000);

